/**
 * \brief Reads models from IR / ONNX / PDPD / TF / TFLite formats.
 * \ingroup ov_core_c_api
 * @param core A pointer to the ov_core_t instance.
 * @param model_path Path to a model.
 * @param bin_path Path to a data file.
 * For IR format (*.bin):
 *  * if {@code bin_path} is empty, will try to read a bin file with the same name as xml and
 *  * if the bin file with the same name is not found, will load IR without weights.
 * For the following file formats the {@code bin_path} parameter is not used:
 *  * ONNX format (*.onnx)
 *  * PDPD (*.pdmodel)
 *  * TF (*.pb)
 *  * TFLite (*.tflite)
 * @param model A pointer to the newly created model.
 * @return Status code of the operation: OK(0) for success.
 */
public static native @Cast("ov_status_e") int ov_core_read_model(@Const ov_core_t core, @Cast("const char*") BytePointer model_path, @Cast("const char*") BytePointer bin_path, @Cast("ov_model_t**") PointerPointer model);
public static native @Cast("ov_status_e") int ov_core_read_model(@Const ov_core_t core, @Cast("const char*") BytePointer model_path, @Cast("const char*") BytePointer bin_path, @ByPtrPtr ov_model_t model);
public static native @Cast("ov_status_e") int ov_core_read_model(@Const ov_core_t core, String model_path, String bin_path, @ByPtrPtr ov_model_t model);

